create schema if not exists ged;
create extension if not exists pgcrypto;
create table if not exists ged.uat_test_plan (id uuid primary key default gen_random_uuid(),tenant_id uuid null,plan_code varchar(80) not null,title text not null,description text null,status varchar(40) not null default 'DRAFT',release_version text null,started_at timestamptz null,finished_at timestamptz null,created_by uuid null,created_at timestamptz not null default now(),updated_at timestamptz null,reg_status char(1) not null default 'A');
create table if not exists ged.uat_test_case (id uuid primary key default gen_random_uuid(),tenant_id uuid null,plan_id uuid null references ged.uat_test_plan(id),module_code varchar(80) not null,case_code varchar(80) not null,title text not null,description text null,preconditions text null,steps text not null,expected_result text not null,priority varchar(30) not null default 'MEDIUM',status varchar(40) not null default 'PENDING',display_order integer not null default 0,created_at timestamptz not null default now(),reg_status char(1) not null default 'A');
create table if not exists ged.uat_test_run (id uuid primary key default gen_random_uuid(),tenant_id uuid null,plan_id uuid not null references ged.uat_test_plan(id),started_by uuid null,started_at timestamptz not null default now(),finished_at timestamptz null,status varchar(40) not null default 'RUNNING',total_cases integer not null default 0,passed_cases integer not null default 0,failed_cases integer not null default 0,blocked_cases integer not null default 0,notes text null,reg_status char(1) not null default 'A');
create table if not exists ged.uat_test_result (id uuid primary key default gen_random_uuid(),tenant_id uuid null,run_id uuid not null references ged.uat_test_run(id),test_case_id uuid not null references ged.uat_test_case(id),result varchar(40) not null default 'PENDING',actual_result text null,evidence_notes text null,incident_id uuid null,executed_by uuid null,executed_at timestamptz not null default now(),reg_status char(1) not null default 'A');
create table if not exists ged.release_evidence (id uuid primary key default gen_random_uuid(),tenant_id uuid null,source_type varchar(80) not null,source_id uuid null,title text not null,description text null,evidence_type varchar(60) not null default 'TEXT',file_path text null,external_url text null,payload_json jsonb null,captured_by uuid null,captured_at timestamptz not null default now(),reg_status char(1) not null default 'A');
create unique index if not exists ux_uat_test_plan_code on ged.uat_test_plan(coalesce(tenant_id,'00000000-0000-0000-0000-000000000000'::uuid),plan_code) where reg_status='A';
create unique index if not exists ux_uat_test_case_plan_code on ged.uat_test_case(plan_id,case_code) where reg_status='A';
create index if not exists ix_uat_test_result_run on ged.uat_test_result(run_id,result);
create index if not exists ix_release_evidence_source on ged.release_evidence(source_type,source_id);
